/* Shared visual components: every view uses the same exact emblem coordinates. */
window.MAX_COLLECTION_VIEWS={create({D,R,esc,badge,I}){
  const level=slug=>D.levels.find(l=>l.slug===slug), reference=id=>R.find(r=>r.id===id);
  const newPose=wardrobeId=>window.MAX_NEW_POSE_ART?.find(item=>item.wardrobeId===wardrobeId);
  const sequences={
    intro:I.models.map(m=>m.id),
    character:['gold','platinum','champion','ruby','emerald','amethyst','prestige','private','premier','reserve'],
    collection:D.wardrobes.map(w=>w.slugs[0])
  };
  const positions={intro:0,character:0,collection:0}, ranks={};
  function character(l,cls='',eager=false,withEmblem=true){
    if(typeof l==='string')l=level(l);
    const r=reference(l.outfit.ref),e=l.outfit.emblem;
    const emblem=withEmblem?`<img class="character-emblem" src="${l.badge}" alt="${esc(l.name)}: official ${esc(l.wingLabel.toLowerCase())}, attached below NB" width="512" height="512" loading="${eager?'eager':'lazy'}" style="left:${e.x}%;top:${e.y}%;width:${e.width}%">`:'';
    return `<span class="character-canvas ${cls}" data-character-level="${l.slug}" style="--art-ratio:${r.width}/${r.height}"><img class="character-base" src="${r.image}" alt="${esc(r.description)}" width="${r.width}" height="${r.height}" loading="${eager?'eager':'lazy'}" decoding="async">${emblem}</span>`;
  }
  const cardBadge=l=>`<span class="card-corner-badge" data-card-badge="${l.slug}">${badge(l)}<small>${esc(l.name)}</small></span>`;
  function pairedCardArt(l,eager=false){
    const pose=newPose(l.wardrobeId),primary=character(l,'',eager,false);
    if(!pose)return `<span class="collection-card-art"><span class="collection-card-art-panel">${primary}</span></span>`;
    return `<span class="collection-card-art is-paired" data-paired-wardrobe="${l.wardrobeId}"><span class="collection-card-art-panel" data-art-label="Gesture">${primary}</span><span class="collection-card-art-panel supplied-pose-panel" data-art-label="Cane pose"><img src="${pose.image}" alt="${esc(pose.description)}" width="${pose.width}" height="${pose.height}" loading="${eager?'eager':'lazy'}" decoding="async"></span></span>`;
  }
  function introCardArt(m,eager=false){
    return `<span class="collection-card-art is-paired intro-card-pair" data-paired-intro="${m.id}">${m.views.slice(0,2).map(view=>`<span class="collection-card-art-panel" data-art-label="${esc(view.label)}">${I.artwork(view.ref,'',eager)}</span>`).join('')}</span>`;
  }
  const inspect=(l,label='Inspect this outfit')=>`<button type="button" class="text-link" data-outfit="${l.slug}">${label} <span aria-hidden="true">↗</span></button>`;
  function annotated(l){
    const as=l.outfit.annotations;
    return `<div class="annotated-stage" aria-label="Annotated ${l.name} outfit"><div class="detail-figure">${character(l,'',true)}</div><svg class="annotation-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${as.map((a,i)=>{const x=20+a.x*.6,sx=a.side==='left'?17.5:82.5,elbow=a.side==='left'?23:77;return `<path data-line="${i}" class="${i===0?'selected-line':''}" d="M ${sx} ${a.row} L ${elbow} ${a.row} L ${x} ${a.y}"></path>`;}).join('')}</svg>${as.map((a,i)=>{const x=a.buttonX??a.x,y=a.buttonY??a.y;return `<button type="button" class="annotation-label ${a.side}" style="top:${a.row}%" data-annotation="${i}" aria-pressed="${i===0}"><span class="eyebrow">0${i+1}</span><strong>${a.title}</strong><small>${esc(i===2?l.wingLabel:a.finish)}</small></button><button type="button" class="hotspot" data-annotation="${i}" aria-label="Detail ${i+1}: ${a.title}" aria-pressed="${i===0}" style="--x:${x};--desktop-x:${20+x*.6};left:calc(var(--desktop-x)*1%);top:${y}%">${i+1}</button>`;}).join('')}</div>`;
  }
  function closeups(l){
    const labels=[['Layer & texture','The neckwear and patterned centre.'],['The exact chest emblem',`${l.name} · ${l.wingLabel.toLowerCase()}.`],['Cuff & gesture','The finishing detail beside the hand.']];
    return `<div class="craft-grid">${l.outfit.closeups.map(([x,y],i)=>`<figure><div class="craft-closeup composition-closeup" style="--crop-left:${50-x*4}%;--crop-top:${50-y*6}%">${character(l)}<button type="button" class="circle-button" data-outfit="${l.slug}" data-focus="${x},${y}" aria-label="Inspect ${labels[i][0]}">↗</button></div><figcaption><strong>${labels[i][0]}</strong>${labels[i][1]}</figcaption></figure>`).join('')}</div>`;
  }
  function selected(key){if(key==='intro')return I.models[positions.intro];const base=level(sequences[key][positions[key]]);return level(ranks[key+':'+base.wardrobeId]||base.slug);}
  function carouselBody(key){
    if(key==='intro')return I.carouselBody(positions.intro);
    const l=selected(key),w=D.wardrobes.find(w=>w.id===l.wardrobeId),i=positions[key],characterMode=key==='character';
    return `<article class="collection-slide" role="group" aria-roledescription="slide" aria-label="${i+1} of ${sequences[key].length}: ${l.name}"><figure class="collection-portrait">${character(l,'',true)}<figcaption>${w.pose} <span>Generated wardrobe proposal</span></figcaption></figure><div class="collection-story"><span class="eyebrow">${characterMode?'Body language / '+w.name:'The complete ensemble'}</span><h3>${characterMode?w.pose:l.name}<span>.</span></h3><p class="collection-description">${characterMode?w.gesture:w.subtitle}</p>${characterMode?`<div class="gesture-context"><span class="eyebrow">Where Max helps</span><p>${w.context}</p><blockquote>${esc(w.voice||'“Let me show you the details.”')}</blockquote></div>`:`<dl class="carousel-garments">${[w.id==='member'?'Silhouette':'Coat','Layers','Trousers','Footwear'].map((name,n)=>`<div><dt>${name}</dt><dd>${w.garments[n]}</dd></div>`).join('')}</dl>`}<div class="carousel-rank-group"><span class="eyebrow">${w.slugs.length>1?'Same wardrobe / Select a rank':'The foundation emblem'}</span><div class="carousel-ranks">${w.slugs.map(s=>`<button type="button" data-carousel-rank="${s}" data-carousel="${key}" aria-pressed="${l.slug===s}">${badge(level(s))}<span>${level(s).name}</span></button>`).join('')}</div><p class="carousel-family-note">${w.slugs.length>1?'Only the chest shield and wings change. The complete ensemble stays together.':'An individual foundation design in the official programme.'}</p></div><div class="button-row"><a class="button secondary" href="#wardrobe/${l.slug}">Explore the details <span aria-hidden="true">→</span></a>${inspect(l,'Enlarge artwork')}</div></div></article>`;
  }
  function carousel(key,{title='The wardrobe collection.',intro='Explore the complete ensemble, its gesture and the ranks it belongs to.',eyebrow='Wardrobe / 15 designs · 28 levels'}={}){
    return `<section class="collection-showcase section-spaced rule" id="collection-${key}" aria-roledescription="carousel" aria-label="${esc(title)}" data-carousel-root="${key}"><div class="section-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${intro?`<p>${intro}</p>`:''}</div><div class="carousel-navigation ${key==='intro'?'intro-carousel-navigation':''}">${key==='intro'?'':`<label class="carousel-picker"><span class="sr-only">Choose a ${key==='character'?'character gesture':'wardrobe'}</span><select data-carousel-select="${key}">${sequences[key].map((s,i)=>{const l=level(s),w=D.wardrobes.find(w=>w.id===l.wardrobeId),name=key==='character'?w.pose:l.name;return `<option value="${i}" ${positions[key]===i?'selected':''}>${String(i+1).padStart(2,'0')} / ${name}</option>`;}).join('')}</select></label>`}<div class="carousel-controls"><button type="button" class="tour-control" data-tour="${key}" aria-pressed="true">Pause tour</button><span class="carousel-counter" data-carousel-counter="${key}" aria-live="polite">${String(positions[key]+1).padStart(2,'0')} / ${String(sequences[key].length).padStart(2,'0')}</span><button type="button" class="circle-button" data-carousel="${key}" data-carousel-step="-1" aria-label="Previous ${key==='character'?'gesture':'wardrobe'}">←</button><button type="button" class="circle-button" data-carousel="${key}" data-carousel-step="1" aria-label="Next ${key==='character'?'gesture':'wardrobe'}">→</button></div></div><div class="carousel-body" id="carousel-${key}" aria-live="off" aria-atomic="false" tabindex="0" aria-label="Use left and right arrow keys to browse" data-carousel-keys="${key}">${carouselBody(key)}</div><div class="carousel-progress" aria-hidden="true"><span data-carousel-progress="${key}" style="width:${100/sequences[key].length}%;left:${positions[key]*100/sequences[key].length}%"></span></div></section>`;
  }
  function move(key,delta){positions[key]=(positions[key]+delta+sequences[key].length)%sequences[key].length;return positions[key];}
  function choose(key,index){positions[key]=Math.max(0,Math.min(sequences[key].length-1,index));}
  function chooseRank(key,slug){if(key==='intro')return;const l=level(slug);if(l.wardrobeId===selected(key).wardrobeId)ranks[key+':'+l.wardrobeId]=slug;}
  function rankSummary(l){const w=D.wardrobes.find(w=>w.id===l.wardrobeId);return `<section class="rank-summary"><div class="rank-summary-emblem"><button type="button" data-badge="${l.slug}" aria-label="Inspect official ${l.name} emblem">${badge(l)}</button><div><span class="eyebrow">Level ${String(l.number).padStart(2,'0')} / 28</span><h2>${l.name}</h2><p>${l.wingLabel}</p></div></div><div><span class="eyebrow">${w.slugs.length>1?'One wardrobe / '+w.slugs.length+' ranks':'Foundation wardrobe'}</span><p>${l.outfit.change}</p></div></section>`;}
  function cardGrid(key,{title='The wardrobe collection.',intro='',eyebrow='Wardrobe collection'}={}){
    const introBadges={'gothic':'reserve','navy-red':'gold','classic-gold':'gold','emerald':'emerald'};
    const cards=key==='intro'?I.models.map((m,i)=>`<a class="collection-card has-paired-art" data-intro-card="${m.id}" href="${m.detail}">${introCardArt(m,i<2)}<span class="collection-card-copy">${cardBadge(level(introBadges[m.id]))}<span class="eyebrow">Outfit model / ${String(i+1).padStart(2,'0')}</span><h3>${esc(m.name)}</h3><span class="collection-card-description">${esc(m.subtitle)}</span><span class="collection-card-data"><span><small>Views</small>${m.views.length} selected ${m.views.length===1?'view':'views'}</span><span><small>Key detail</small>${esc(m.garments[0])}</span></span><strong>Open complete page →</strong></span></a>`).join(''):sequences[key].map((slug,i)=>{const l=level(slug),w=D.wardrobes.find(w=>w.id===l.wardrobeId),characterMode=key==='character',paired=Boolean(newPose(w.id)),rankNames=w.slugs.map(s=>level(s).name).join(','),content=`${pairedCardArt(l,i<2)}<span class="collection-card-copy">${cardBadge(l)}<span class="eyebrow">${characterMode?'Gesture '+String(i+1).padStart(2,'0'):w.slugs.length+' '+(w.slugs.length===1?'rank':'ranks')}</span><h3>${esc(characterMode?w.pose:w.name)}</h3><span class="collection-card-description">${esc(characterMode?w.gesture:w.subtitle)}</span><span class="collection-card-data"><span><small>Ranks</small>${esc(rankNames)}</span><span><small>${characterMode?'Use':'Key detail'}</small>${esc(characterMode?w.context:w.garments[0])}</span></span><strong>${characterMode?'Open character page':'Open wardrobe study'} →</strong></span>`;return characterMode?`<a class="collection-card${paired?' has-paired-art':''}" data-character-card="${l.slug}" href="#story/${l.slug}">${content}</a>`:`<a class="collection-card${paired?' has-paired-art':''}" data-wardrobe-card="${l.slug}" href="#detail/${l.slug}">${content}</a>`;}).join('');
    return `<section class="collection-card-section section-spaced rule" data-card-collection="${key}"><div class="section-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${intro?`<p>${intro}</p>`:''}</div><div class="collection-card-grid">${cards}</div></section>`;
  }
  function wardrobeRail(){return `<section class="wardrobe-shelf section-spaced rule" data-shelf-root="wardrobe"><div class="section-head"><div><span class="eyebrow">The full collection</span><h2>Fifteen considered wardrobes.</h2></div><div class="shelf-buttons"><button type="button" class="tour-control" data-shelf-tour="wardrobe" aria-pressed="true">Pause tour</button><button class="circle-button" type="button" data-shelf="-1" aria-label="Previous wardrobes">←</button><button class="circle-button" type="button" data-shelf="1" aria-label="Next wardrobes">→</button></div></div><div class="outfit-carousel" id="wardrobe-shelf" tabindex="0" aria-label="Wardrobes; swipe or use the arrow buttons">${D.wardrobes.map(w=>{const l=level(w.slugs[0]);return `<a class="outfit-mini" href="#wardrobe/${l.slug}">${character(l)}<h3>${w.name}</h3><p>${w.slugs.length===1?'One foundation level':w.slugs.length+' ranks · one ensemble'}</p></a>`;}).join('')}</div></section>`;}
  return {character,annotated,closeups,carousel,carouselBody,move,choose,chooseRank,selected,positions,sequences,rankSummary,wardrobeRail,cardGrid};
}};
